function prng(seed){var a=seed>>>0||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var R=prng(70001);
var T0=Date.now();
var RP=3,N=500,D=5;
var base=[];for(var i=0;i<N;i++)base.push(Math.floor(R()*1e9));
function root(a){var h=0;for(var i=0;i<a.length;i++)h=((h*31+a[i])>>>0);return h;}
var r0=root(base),reps=[];
for(var r=0;r<RP;r++){var cp=base.slice();for(var d=0;d<D;d++)cp[Math.floor(R()*N)]=Math.floor(R()*1e9);reps.push(cp);}
var bad=0;reps.forEach(function(cp){if(root(cp)!==r0)bad++;});
reps.forEach(function(cp){for(var i=0;i<N;i++)if(cp[i]!==base[i])cp[i]=base[i];});
var fixed=reps.every(function(cp){return root(cp)===r0;});
console.log(JSON.stringify({id:"JAH-APX70-000001",ok:true,metrics:{replicas:RP,records:N,diverged_detected:bad,repaired:fixed,root_hash:r0},ms:Date.now()-T0}));

